         this.actuallyHurt(level, source, damage);
         this.hurtDuration = 10;
         this.hurtTime = this.hurtDuration;
      }

      this.resolveMobResponsibleForDamage(source);
      this.resolvePlayerResponsibleForDamage(source);
      if (tookFullDamage) {
